# Check all installed packages for cellspec
import os, sys

def search_dir(d):
    if not os.path.exists(d):
        return []
    results = []
    for root, dirs, files in os.walk(d):
        for f in files:
            if 'cell' in f.lower() or 'undil' in f.lower():
                results.append(os.path.join(root, f))
        # Limit recursion depth
        if len(dirs) > 20:
            dirs[:] = []  # Stop descending into too many dirs
    return results

# Search current site-packages
site_pkgs = os.path.dirname(sys.executable).replace('/bin/python', '/lib/python3.11/site-packages')
for f in search_dir(site_pkgs):
